    GraphPathImpl<V, E> path = new GraphPathImpl<>(graph, null, null, 0.0);
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        path.setStartVertex(source);
        path.setEndVertex(target);
        path.addEdge(edge);
        path.setWeight(path.getWeight() + graph.getEdgeWeight(edge));
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    DefaultDirectedWeightedGraph<V, E> pathGraph = new DefaultDirectedWeightedGraph<>(graph.getEdgeFactory());
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (!pathGraph.containsVertex(source)) {
            pathGraph.addVertex(source);
        }
        if (!pathGraph.containsVertex(target)) {
            pathGraph.addVertex(target);
        }
        pathGraph.addEdge(source, target, edge);
        pathGraph.setEdgeWeight(edge, graph.getEdgeWeight(edge));
    }
    return new GraphWalk<>(graph, pathGraph.vertexSet().iterator().next(), 
                           pathGraph.vertexSet().iterator().next(), 
                           new ArrayList<>(pathGraph.edgeSet()), 
                           pathGraph.edgeSet().stream().mapToDouble(graph::getEdgeWeight).sum());
}

