public static String applyRelativePath(String path, String relativePath) {
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");

    int index = pathParts.length - 1;
    for (String part : relativeParts) {
        if (part.equals("..")) {
            if (index > 0) {
                index--;
            }
        } else if (!part.equals(".")) {
            break;
        }
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= index; i++) {
        result.append(pathParts[i]);
        result.append("/");
    }

    for (int i = 0; i < relativeParts.length; i++) {
        if (!relativeParts[i].equals("..") && !relativeParts[i].equals(".")) {
            result.append(relativeParts[i]);
            if (i < relativeParts.length - 1 || pathParts.length == 1 || index == 0) {
                result.append("/");
            }
        }
    }

    return result.toString();
}

String function ( String path , String relativePath ) { 
    if ( relativePath.startsWith("/") ) {
        return relativePath; // If relativePath is absolute, return it directly
    }
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    int pathLength = pathParts.length;
    int i = 0;

    // Traverse the relative path parts
    for (String part : relativeParts) {
        if (part.equals("..")) {
            if (pathLength > 1) { // Avoid going above the root
                pathLength--;
            }
        } else if (!part.equals(".")) {
            pathParts[pathLength++] = part;
        }
    }

    // Join the parts back into a single path
    StringBuilder result = new StringBuilder();
    for (i = 0; i < pathLength; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathParts[i]);
    }

    return result.toString();
}

